import {escapeHTML as esc} from './real-data.js';
const clean=name=>name.replace(/^\d+\.\s*/,'').replace(/^Stage\s+\d+:\s*/i,'');
export function activityRing(n){
 const total=n.total||1,parts=[['man',n.manual],['hyb',n.semi],['auto',n.auto]];
 let offset=0;
 return `<div class="tw-mix-ring" role="img" aria-label="Activity mix: ${n.manual} manual, ${n.semi} semi-automated, ${n.auto} automated"><svg viewBox="0 0 120 120" aria-hidden="true"><circle class="ring-track" cx="60" cy="60" r="48"/>${parts.map(([type,value])=>{const size=value/total*100,mark=`<circle class="ring-${type}" cx="60" cy="60" r="48" pathLength="100" stroke-dasharray="${size} ${100-size}" stroke-dashoffset="${-offset}"/>`;offset+=size;return mark}).join('')}</svg><span><b>${Math.round(n.manual/total*100)}%</b><small>Manual Activities</small></span></div>`;
}
export function overviewVisuals(t){
 const maxActivity=Math.max(1,...t.stages.map(s=>s.total));
 const allFlows=t.handoffGraph.flows.map((f,index)=>({...f,index}));
 const flows=allFlows.length>9?[...allFlows].sort((a,b)=>(b.inCount+b.outCount)-(a.inCount+a.outCount)).slice(0,9):allFlows,maxHandoffs=Math.max(1,...flows.map(f=>f.inCount+f.outCount));
 return `<div class="tw-insights"><section class="tw-chart" aria-labelledby="tw-volume-title"><div class="tw-section-title"><h2 id="tw-volume-title">Activity Volume by Stage</h2><span>Documented Activities</span></div><p class="tw-chart-intro">Compare activity volume and automation mix. Select a stage to explore its process.</p><div class="tw-chart-legend"><span><i class="tw-dot man"></i>Manual</span><span><i class="tw-dot hyb"></i>Semi-Automated</span><span><i class="tw-dot auto"></i>Automated</span></div><div class="tw-chart-rows">${t.stages.map((s,i)=>`<button class="tw-chart-row" data-stage="${esc(s.id)}" aria-label="Stage ${i+1}, ${esc(clean(s.name))}: ${s.total} activities, ${s.counts.man} manual, ${s.counts.hyb} semi-automated, ${s.counts.auto} automated"><span class="tw-chart-label"><small>${String(i+1).padStart(2,'0')}</small>${esc(clean(s.name))}</span><span class="tw-chart-track"><span class="tw-chart-bar" style="width:${s.total/maxActivity*100}%">${[['man',s.counts.man],['hyb',s.counts.hyb],['auto',s.counts.auto]].map(([k,v])=>`<i class="${k}" style="flex-grow:${v}"></i>`).join('')}</span></span><b>${s.total}</b></button>`).join('')}</div><div class="tw-chart-axis"><span>0</span><span>${maxActivity} Activities</span></div></section><section class="tw-chart" aria-labelledby="tw-handoff-title"><div class="tw-section-title"><h2 id="tw-handoff-title">Handoff Load by Flow</h2><span>Documented Connections</span></div><p class="tw-chart-intro">See where work crosses teams. Select a flow to trace its connections.</p><div class="tw-chart-legend"><span><i class="tw-dot inbound"></i>Inbound</span><span><i class="tw-dot outbound"></i>Outbound</span></div><div class="tw-chart-rows">${flows.map((f,i)=>`<button class="tw-chart-row" data-chart-flow="${f.index}" aria-label="${esc(clean(f.title))}: ${f.inCount} inbound and ${f.outCount} outbound connections"><span class="tw-chart-label"><small>${String(f.index+1).padStart(2,'0')}</small>${esc(clean(f.title))}</span><span class="tw-chart-track"><span class="tw-chart-bar" style="width:${(f.inCount+f.outCount)/maxHandoffs*100}%"><i class="inbound" style="flex-grow:${f.inCount}"></i><i class="outbound" style="flex-grow:${f.outCount}"></i></span></span><b>${f.inCount+f.outCount}</b></button>`).join('')}</div><div class="tw-chart-axis"><span>0</span><span>${maxHandoffs} Connections</span></div><p class="tw-note">${allFlows.length>9?`Showing the 9 most-connected flows of ${allFlows.length}. <button class="tw-text-button" data-chart-handoffs>Explore All Flows →</button><br>`:''}Repeated connections are counted as recorded in the source.</p></section></div>`;
}
